import torch
import torch.nn as nn

class DenseLayer(nn.Module):
    def __init__(self, in_c, growth_rate):
        super().__init__()
        self.bn = nn.BatchNorm2d(in_c)
        self.relu = nn.ReLU(inplace=True)
        self.conv = nn.Conv2d(in_c, growth_rate, kernel_size=3, padding=1, bias=False)

    def forward(self, x):
        out = self.conv(self.relu(self.bn(x)))
        return torch.cat([x, out], dim=1)  # concat with all previous features

class DenseBlock(nn.Module):
    def __init__(self, in_c, growth_rate, num_layers):
        super().__init__()
        layers = []
        for i in range(num_layers):
            layers.append(DenseLayer(in_c + i * growth_rate, growth_rate))
        self.block = nn.Sequential(*layers)

    def forward(self, x):
        return self.block(x)

class TransitionBlock(nn.Module):
    def __init__(self, in_c, out_c):
        super().__init__()
        self.bn = nn.BatchNorm2d(in_c)
        self.conv = nn.Conv2d(in_c, out_c, kernel_size=1, bias=False)
        self.pool = nn.AvgPool2d(kernel_size=2, stride=2)

    def forward(self, x):
        return self.pool(self.conv(torch.relu(self.bn(x))))

# Example usage
x = torch.randn(1, 64, 32, 32)
dense = DenseBlock(in_c=64, growth_rate=32, num_layers=4)
out = dense(x)
print("After dense block:", out.shape)  # channels grow by 32*4
trans = TransitionBlock(in_c=out.shape[1], out_c=out.shape[1] // 2)
print("After transition:", trans(out).shape)

import torch
from torchvision import models

model = models.vgg16(weights=models.VGG16_Weights.DEFAULT)
model.eval()

# Choose intermediate layers by index in model.features
layers_of_interest = {'3': 'relu1_2', '8': 'relu2_2', '15': 'relu3_3', '22': 'relu4_3'}

features = {}

def get_hook(name):
    def hook(module, input, output):
        features[name] = output.detach()
    return hook

handles = []
for idx, name in layers_of_interest.items():
    layer = model.features[int(idx)]
    handles.append(layer.register_forward_hook(get_hook(name)))

x = torch.randn(1, 3, 224, 224)
with torch.no_grad():
    _ = model(x)  # single forward pass fills 'features' dict for all layers at once

for name, feat in features.items():
    print(name, feat.shape)

# Clean up hooks when done
for h in handles:
    h.remove()
